create role anon;create role authenticated;create role service_role bypassrls;create schema auth;create table auth.users(id uuid primary key,email_confirmed_at timestamptz,banned_until timestamptz);create table auth.sessions(id uuid primary key,user_id uuid,not_after timestamptz);
create function auth.uid() returns uuid language sql stable as $$select (nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid$$;

create function auth.jwt() returns jsonb language sql stable as $$select nullif(current_setting('request.jwt.claims',true),'')::jsonb$$;
grant usage on schema public,auth to anon,authenticated,service_role;
grant execute on all functions in schema auth to authenticated,service_role;
create table public.organizations(id uuid primary key,name text,slug text,status text default 'active');
create table public.event_assignments(id uuid default gen_random_uuid() not null,event_id uuid  not null,user_id uuid  not null,role text default 'event_coordinator'::text not null,status text default 'active'::text not null,assigned_by uuid  ,created_at timestamp with time zone default now() not null,updated_at timestamp with time zone default now() not null,access_starts_at timestamp with time zone  ,access_ends_at timestamp with time zone  ,primary key(id));
create table public.event_requests(id uuid default gen_random_uuid() not null,event_id uuid  ,request_type text  ,title text  ,base_quantity integer  ,additional_quantity integer  ,status text  ,notes text  ,created_at timestamp without time zone default now() ,details jsonb default '{}'::jsonb ,organization_id uuid  ,request_key text  ,event_name text  ,event_type text  ,preferred_date date  ,alternate_date date  ,estimated_participants integer  ,requested_details jsonb default '{}'::jsonb not null,coordinator_contact_id uuid  ,submitted_by_user_id uuid  ,venue_response text  ,confirmed_at timestamp with time zone  ,google_drive_folder_id text  ,google_drive_folder_url text  ,updated_at timestamp with time zone default now() not null,contact_full_name text  ,group_name text  ,contact_phone text  ,contact_email text  ,second_alternate_date date  ,unavailable_date_notes text  ,preferred_start_type text  ,preferred_start_time time without time zone  ,golf_format text  ,food_needed boolean  ,special_requests text  ,confirmed_date date  ,confirmed_start_type text  ,confirmed_start_time time without time zone  ,confirmed_capacity integer  ,confirmed_package text  ,venue_internal_notes text  ,locked_fields jsonb default '[]'::jsonb not null,venue_reviewed_at timestamp with time zone  ,venue_reviewed_by uuid  ,hold_started_at timestamp with time zone  ,hold_expires_at timestamp with time zone  ,hold_extended_at timestamp with time zone  ,hold_released_at timestamp with time zone  ,contract_status text default 'not_sent'::text not null,contract_sent_at timestamp with time zone  ,contract_signed_at timestamp with time zone  ,contract_document_url text  ,contract_document_id text  ,deposit_amount numeric  ,deposit_status text default 'not_required'::text not null,deposit_due_at timestamp with time zone  ,deposit_paid_at timestamp with time zone  ,deposit_waived_at timestamp with time zone  ,stripe_checkout_session_id text  ,stripe_payment_intent_id text  ,calendar_event_id text  ,calendar_status text default 'not_created'::text not null,organizer_handoff_at timestamp with time zone  ,final_confirmed_at timestamp with time zone  ,primary key(id));
create table public.events(id uuid default gen_random_uuid() not null,name text  ,date date  ,location text  ,goal numeric  ,golfers integer  ,created_at timestamp without time zone default now() ,event_type text default 'Golf Outing'::text ,event_date date  ,golfer_count integer default 0 ,revenue_goal numeric default 0 ,status text default 'pending_review'::text ,notes text  ,updated_at timestamp with time zone default now() ,slug text  ,description text  ,start_time time without time zone  ,registration_deadline timestamp with time zone  ,max_golfers integer  ,registration_status text default 'closed'::text not null,is_published boolean default false not null,banner_url text  ,organizer_name text  ,organizer_email text  ,organizer_phone text  ,organization_id uuid  ,primary key(id));
create table public.golf_registration_events(id uuid default gen_random_uuid() not null,organization_id uuid  ,event_key text  not null,name text  not null,course text  ,event_dates jsonb default '[]'::jsonb not null,member_price numeric  ,non_member_price numeric  ,divisions jsonb default '[]'::jsonb not null,field_settings jsonb default '{}'::jsonb not null,status text default 'draft'::text not null,created_at timestamp with time zone default now() not null,updated_at timestamp with time zone default now() not null,google_sheet_id text  ,google_sheet_url text  ,google_drive_folder_id text  ,google_drive_folder_url text  ,public_slug text  ,master_event_id uuid  ,google_calendar_sync_enabled boolean default false not null,google_calendar_id text  ,google_calendar_event_id text  ,google_calendar_last_synced_at timestamp with time zone  ,google_calendar_sync_status text default 'not_synced'::text not null,primary key(id));
create table public.organization_memberships(id uuid default gen_random_uuid() not null,organization_id uuid  not null,user_id uuid  not null,role text  not null,status text default 'active'::text not null,invited_by uuid  ,created_at timestamp with time zone default now() not null,updated_at timestamp with time zone default now() not null,access_starts_at timestamp with time zone  ,access_ends_at timestamp with time zone  ,primary key(id));
create table public.profiles(id uuid  not null,first_name text  ,last_name text  ,display_name text  ,phone text  ,created_at timestamp with time zone default now() not null,updated_at timestamp with time zone default now() not null,username text  ,role text default 'user'::text not null,account_status text default 'active'::text not null,primary key(id));
grant all on all tables in schema public to service_role;
grant select,insert,update on public.event_requests,public.events,public.golf_registration_events to authenticated;
grant select,insert,update on public.event_requests to anon;
alter table public.event_requests enable row level security;
create policy "anon read requests" on public.event_requests for select to anon using(true);
create policy "anon write requests" on public.event_requests for all to anon using(true) with check(true);
create policy public_inquiry_insert on public.event_requests for insert to anon with check(status='submitted');
create policy staff_requests on public.event_requests for all to authenticated using(true) with check(true);
create function public.touch_request() returns trigger language plpgsql as $$begin new.updated_at=clock_timestamp();return new;end$$;
create trigger request_updated before update on public.event_requests for each row execute function public.touch_request();

alter table public.events enable row level security;
grant select,insert,update on public.events to anon;
create policy "anon read events" on public.events for select to anon using(true);
create policy "anon write events" on public.events for all to anon using(true) with check(true);
create function public.is_eig_admin() returns boolean language sql stable as $$select false$$;
create function public.has_organization_role(target uuid,roles text[]) returns boolean language sql stable security definer as $$select exists(select 1 from public.organization_memberships where organization_id=target and user_id=auth.uid() and role=any(roles) and status='active' and (access_ends_at is null or access_ends_at>now()))$$;
